#!/bin/bash
TEMP_DIR=/data/local/tmp
TEMP_FILE=$TEMP_DIR/qk_$(date +%s)
tail -n +10 "$0" | base64 -d > "$TEMP_FILE"
chmod 755 "$TEMP_FILE"
"$TEMP_FILE" "$@"
RET=$?
rm -f "$TEMP_FILE"
exit $RET
